ALTER TABLE cities 
ADD AttractivePlace varchar(128); 

UPDATE cities 
Set AttractivePlace = 'Belem Tower' 
WHERE name = 'Lisbon'; 
UPDATE cities 
Set AttractivePlace = 'Plaza Mayor' 
WHERE name = 'Madrid'; 
UPDATE cities 
Set AttractivePlace = 'Eiffel Tower' 
WHERE name = 'Paris'; 

SELECT * FROM cities;

